(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.013+t*0.15)*9 + Math.cos((y+w1y)*0.011-t*0.18)*7;
  const w2y = Math.cos((y+w1y)*0.014-t*0.12)*9 + Math.sin((x+w1x)*0.012+t*0.2)*7;
  const w3x = Math.sin((x+w2x)*0.008+t*0.1)*5 + Math.cos((y+w2y)*0.007-t*0.08)*4;
  const w3y = Math.cos((y+w2y)*0.009-t*0.07)*5 + Math.sin((x+w2x)*0.006+t*0.12)*4;
  const sx = x+w1x+w2x+w3x, sy = y+w1y+w2y+w3y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+2)*50,0.11,2.1],
    [400+Math.cos(t*0.55+1)*70,220+Math.sin(t*0.75+4)*40,0.05,1.8]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3)*0.5;
  }
  const act=aS/8,inh=iS/8,harm=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*6+t*2)*0.15;
  const cross=Math.sin(sx*0.18+t*0.7)*Math.sin(sy*0.18-t*0.6)*0.12;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+harm*0.2+cross)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const contour=(Math.sin(reaction*14)*0.5+0.5)*(Math.abs(reaction)>0.45?1:0)*0.12;
  const shimmer=Math.sin(sx*0.3+sy*0.2+t*4)*Math.sin(sx*0.15-sy*0.25-t*3)*0.06*Math.max(0,reaction);
  const blend=reaction*0.6+cell*0.18+contour*0.12+shimmer*0.1,v=blend*0.5+0.5;
  const pal=[[10,20,68],[16,52,105],[22,92,125],[30,140,130],[80,162,115],[150,175,80],[195,178,58],[218,132,55],[200,78,52],[148,42,62],[78,24,58],[10,20,68]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.86+Math.sin(reaction*Math.PI)*0.14+contour*0.6+shimmer*2;
  const edge=Math.abs(reaction)>0.7?1.12:Math.abs(reaction)<0.08?0.9:1.0;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
